import{_ as n,l,o as e,c as i,v as t,p as s,x as r,d as c,i as d,S as p}from"./chunks/framework.InCnrqk-.js";const S=JSON.parse('{"title":"并发与增量 GC","description":"","frontmatter":{"title":"并发与增量 GC","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/concurrent-incremental-gc.md","filePath":"cs/concurrent-incremental-gc.md","lastUpdated":1789023840000}'),h={name:"cs/concurrent-incremental-gc.md"};function u(_,a,m,B,T,A){const o=l("Mermaid");return e(),i("div",null,[a[1]||(a[1]=t('<h1 id="并发与增量-gc" tabindex="-1">并发与增量 GC <a class="header-anchor" href="#并发与增量-gc" aria-label="Permalink to &quot;并发与增量 GC&quot;">​</a></h1><div class="epigraph"><p>增量把标记切成小片与突变者交错；并发让标记与用户线程真正并行。三色不变式靠读/写屏障维持，否则漏标或悬浮。</p><footer>—— 据 Dijkstra et al., On-the-Fly Garbage Collection；Steele；Jones 手册；G1/CMS 实践对照整理</footer></div><p>上一课<a href="/cs/write-barrier-card-table">写屏障与卡表</a> 给了记录写入的钩子。缺口是<strong>缩短停顿</strong>：增量/并发标记。本课钉三色（白灰黑）与屏障选择，分代晋升下一课。不把某个 JVM 收集器当唯一理论。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>Stop-the-world 复制简单，延迟差。并发：突变者同时改图。Dijkstra：写屏障维持不变式。现代：SATB（snapshot-at-the-beginning）或增量更新。缺口是<strong>与突变者的合同</strong>，不是卡表字节。</p><p>增量：STW 但切片，仍要世界一致的根。</p><h3 id="并发-gc-不是「无暂停」" tabindex="-1">并发 GC 不是「无暂停」 <a class="header-anchor" href="#并发-gc-不是「无暂停」" aria-label="Permalink to &quot;并发 GC 不是「无暂停」&quot;">​</a></h3><p>通常有短 STW（根扫描、再标记）。无暂停要更强（Azul、Shenandoah 的进步点名），代价更高。</p><p><span class="marginnote">Dijkstra, Lamport, Martin, Scholten。Yuasa SATB。CMS/G1/Shenandoah。Jones 手册并发章。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>三色：黑=扫完，灰=待扫，白=未访问。结束时白是垃圾。屏障：防止黑指向白而不灰。实现选 SATB 或增量更新。</p>',11)),(e(),s(p,null,{default:r(()=>[d(o,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20MUT%5B%22%E7%AA%81%E5%8F%98%E8%80%85%22%5D%20--%3E%20BAR%5B%22%E8%AF%BB%2F%E5%86%99%E5%B1%8F%E9%9A%9C%22%5D%0A%20%20BAR%20--%3E%20TRI%5B%22%E4%B8%89%E8%89%B2%E4%B8%8D%E5%8F%98%E5%BC%8F%22%5D%0A%20%20TRI%20--%3E%20REC%5B%22%E5%9B%9E%E6%94%B6%E7%99%BD%E5%AF%B9%E8%B1%A1%22%5D%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[c(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<p>与 JIT：安全点、load 屏障（Brooks/LVB）影响每一条指针读。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>浮动垃圾：SATB 可能把本轮已死当活，下轮收。吞吐换延迟。不要在屏障里分配而无 TLAB 小心再入。</p><p>验证：漏屏障是最毒的 bug。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不写 G1 region 全文。后课默认：低延迟靠屏障+三色。下一课分代假设与晋升。</p><p>也不把并发 GC 当数据库 MVCC 课。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>增量/并发用三色+屏障与突变者共存。</li><li>仍常有短暂停；浮动垃圾换延迟。</li><li>与卡表分代正交，可组合。</li><li>出处：Dijkstra et al.；Jones 手册；Yuasa SATB。</li></ul>',9))])}const f=n(h,[["render",u]]);export{S as __pageData,f as default};
